using System.Text.Json;using System.Security.AccessControl;using System.Security.Principal;
namespace RouterStudio.Core.Services;
public sealed record UserSettings(string Theme="System",bool CloseToTray=false);
public sealed class UserSettingsStore(string root){
 public string? Notice{get;private set;}
 public UserSettings Read(){try{var file=Path.Combine(root,"preferences.json");if(!File.Exists(file))return new();if(new FileInfo(file).Length>4096||(File.GetAttributes(file)&FileAttributes.ReparsePoint)!=0)throw new IOException();var value=JsonSerializer.Deserialize<UserSettings>(File.ReadAllText(file));return value?.Theme is "System" or "Light" or "Dark"?value:new();}catch(Exception ex) when(ex is IOException or UnauthorizedAccessException or JsonException){Notice="Saved preferences could not be read. Defaults are in use.";return new();}}
 public void Save(UserSettings value){try{if(value.Theme is not ("System" or "Light" or "Dark"))return;Directory.CreateDirectory(root);if((File.GetAttributes(root)&FileAttributes.ReparsePoint)!=0)throw new IOException();var security=new DirectorySecurity();security.SetAccessRuleProtection(true,false);foreach(var sid in new[]{WindowsIdentity.GetCurrent().User!,new SecurityIdentifier(WellKnownSidType.LocalSystemSid,null)})security.AddAccessRule(new FileSystemAccessRule(sid,FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));new DirectoryInfo(root).SetAccessControl(security);var file=Path.Combine(root,"preferences.json");foreach(var path in new[]{file,file+".tmp"})if(File.Exists(path)&&(File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new IOException();File.WriteAllText(file+".tmp",JsonSerializer.Serialize(value));File.Move(file+".tmp",file,true);Notice=null;}catch(Exception ex) when(ex is IOException or UnauthorizedAccessException){Notice="Preferences could not be saved. Current choices still apply in this session.";}}
}
